css_snippet:
/* Optimize heading readability */
h1 {
  letter-spacing: -0.02em; /* Slightly tighter for large headings */
  word-spacing: 0.05em;   /* A bit more space between words for balance */
}

/* Enhance small body text legibility */
p.small-text {
  font-size: 0.8em;
  letter-spacing: 0.01em; /* Slightly wider for small text */
  word-spacing: 0.02em;
}

/* Reset for default elements if needed */
body {
  letter-spacing: normal;
  word-spacing: normal;
}
